/*
 * A245187  Trajectory of 1 under repeated applications of the morphism 0->12,
 *          1->12, 2->00.
 * https://oeis.org/A245187
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th symbol of the morphic word generated by
 *            σ(0)=12, σ(1)=12, σ(2)=00 with initial symbol 1. Equivalently,
 *            a(0)=1 and for n>0: if a(floor(n/2)) = 2 -> a(n) = 0 if
 *            a(floor(n/2)) ≠ 2 and n even -> a(n) = 1 if a(floor(n/2)) ≠ 2
 *            and n odd -> a(n) = 2
 * Range:     u8 n <= 119, u16 n <= 119, u32 n <= 119, u64 n <= 119,
 *            u128 n <= 119, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)                 /* base case – first symbol is 1 */
        return (seq_t)1;
    seq_t parent = a(n >> 1);   /* symbol that produced this one */
    if (parent == (seq_t)2)     /* 2 -> 00 */
        return (seq_t)0;
    return (n & 1ULL) ? (seq_t)2 : (seq_t)1;  /* 0 or 1 -> 12 */
}
